class Solution {
public:
    vector<string> findHighAccessEmployees(vector<vector<string>>& access_times) {
        unordered_map<string, vector<int>> d;
        for (auto& e : access_times)
            d[e[0]].push_back(stoi(e[1].substr(0, 2)) * 60 + stoi(e[1].substr(2)));
        vector<string> res;
        for (auto& [name, ts] : d) {
            sort(ts.begin(), ts.end());
            for (size_t i = 0; i + 2 < ts.size(); i++)
                if (ts[i + 2] - ts[i] < 60) { res.push_back(name); break; }
        }
        return res;
    }
};

