class Solution {
    public List<String> findHighAccessEmployees(List<List<String>> accessTimes) {
        Map<String, List<Integer>> d = new HashMap<>();
        for (List<String> e : accessTimes) {
            String t = e.get(1);
            d.computeIfAbsent(e.get(0), k -> new ArrayList<>())
             .add(Integer.parseInt(t.substring(0, 2)) * 60 + Integer.parseInt(t.substring(2)));
        }
        List<String> res = new ArrayList<>();
        for (var en : d.entrySet()) {
            List<Integer> ts = en.getValue();
            Collections.sort(ts);
            for (int i = 0; i + 2 < ts.size(); i++)
                if (ts.get(i + 2) - ts.get(i) < 60) { res.add(en.getKey()); break; }
        }
        return res;
    }
}

